package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaEsDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_sami" to DuaText("Refugio del mal de mis sentidos", "Oh Allah, busco refugio en Ti del mal de mi oído, del mal de mi vista, del mal de mi lengua, del mal de mi corazón y del mal de mi deseo.", "Enseñado a Shakal ibn Humayd (RA).", "Un dua para proteger las extremidades y el yo del pecado."),
        "dua_hadm_gharaq" to DuaText("Refugio contra la muerte súbita y los accidentes", "Oh Allah, busco refugio en Ti de ser aplastado (por un edificio), de caer desde una altura, de ahogarme, de quemarme y de la vejez; de Shaytán que me desvía en el momento de la muerte, de morir mientras huyo de Tu camino y de morir por una picadura (venenosa).", "Refugio de accidentes y malas muertes.", "Un dua de refugio del Profeta ﷺ."),
        "dua_ju_khiyanah" to DuaText("Refugio del hambre y la traición", "Oh Allah, me refugio en Ti contra el hambre, porque es un mal compañero, y me refugio en Ti contra la traición, porque es un mal confidente.", "Refugio del hambre y la traición.", "Un dua de refugio del Profeta ﷺ."),
        "dua_huda_tuqa" to DuaText("Orientación, Piedad, Castidad y Suficiencia", "Oh Allah, te pido guía, piedad, castidad y autosuficiencia.", "Un dua breve y completo del Profeta ﷺ.", "Cuatro bendiciones fundamentales de la religión y de este mundo."),
        "dua_aslih_li_dini" to DuaText("Rectificar mi religión, el mundo y el más allá", "Oh Allah, corrige mi religión, que es la salvaguardia de todos mis asuntos; endereza mi vida mundana, en la que está mi sustento; y enderezar mi Más Allá, al cual regresaré. Hazme de la vida un aumento en todos los bienes, y hazme de la muerte un alivio de todos los males.", "Reformar la religión, este mundo y el Más Allá: los tres.", "Un dua completo del Profeta ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Vuelve nuestros corazones a tu obediencia", "Oh Allah, Turner de corazones, vuelve nuestros corazones a Tu obediencia.", "Un dua para mantener el corazón firme en la obediencia.", "Los corazones de todas las personas están entre dos dedos del Misericordioso."),
        "dua_jannah_nar" to DuaText("Pidiendo Jannah, refugio del fuego", "Oh Allah, te pido el Paraíso y busco refugio en Ti del Fuego.", "Después del tashahhud o en cualquier momento.", "El Profeta ﷺ dijo: nuestros duas también giran en torno a esto."),
        "dua_khayri_kullih" to DuaText("Todo bien, ahora y después", "Oh Allah, te pido todo bien, lo inmediato y lo diferido, lo que sé y lo que no sé, y busco refugio en Ti de todo mal, lo inmediato y lo diferido, lo que sé y lo que no sé. Oh Allah, te pido el Paraíso y cualquier palabra y obra que me acerque a él, y busco refugio en Ti del Fuego y de cualquier palabra y acción que me acerque a él.", "El Profeta ﷺ enseñó este dua integral a Aisha (RA) (parte del dua).", "Una dua que reúne todos los bienes."),
        "dua_ihdini_saddidni" to DuaText("Guíame y mantenme erguido", "Oh Allah, guíame y mantenme en el camino correcto.", "El Profeta ﷺ se lo enseñó a Ali (RA).", "Piense en la guía como ser guiado a lo largo de un camino y en la sadad como la rectitud de una flecha."),
        "dua_hubbaka" to DuaText("Pidiendo el amor de Allah", "Oh Allah, te pido Tu amor, el amor de quienes Te aman y las obras que me lleven a Tu amor. Oh Allah, haz que Tu amor sea más querido para mí que yo mismo, mi familia y el agua fría.", "La dua de Dawud (AS) relatada por el Profeta ﷺ.", "El amor de Allah es la mayor riqueza."),
        "dua_filal_khayrat" to DuaText("Hacer el bien y dejar el mal", "Oh Allah, te pido que me permitas hacer buenas obras, dejar las malas acciones y amar a los pobres, y que me perdones y tengas misericordia de mí. Y cuando quieras poner a prueba a un pueblo, llévame sin ser probado. Te pido tu amor, el amor de quienes te aman y el amor de las obras que me acercan a tu amor.", "Allah le enseñó esta dua al Profeta ﷺ en un sueño.", "El Profeta ﷺ dijo: es verdad, así que aprendedlo y enséñalo."),
        "dua_bi_ilmikal_ghayb" to DuaText("Déjame vivir mientras la vida sea buena", "Oh Allah, por Tu conocimiento de lo invisible y Tu poder sobre la creación, mantenme con vida mientras sepas que la vida es mejor para mí, y tómame cuando sepas que la muerte es mejor para mí. Oh Allah, te pido temor de Ti en privado y en público, palabra de verdad en la alegría y en la ira, y moderación en la pobreza y la riqueza.", "La oración dua de Ammar ibn Yasir (RA) (parte inicial).", "El Profeta ﷺ hizo este dua en oración."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Oh Allah, te lo pido, porque a Ti pertenece toda alabanza; no hay más dios que Tú, el Otorgador de favores, Creador de los cielos y de la tierra. ¡Oh Poseedor de Majestad y Honor, oh Viviente, oh Sustentador!", "El Profeta ﷺ dijo que este hombre hizo dua con el Nombre más grande de Allah.", "Se responde una dua hecha con este Nombre."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "Oh Allah, te lo pido, porque doy testimonio de que Tú eres Allah; no hay más dios que Tú, el Único, el Autosuficiente, que ni engendra ni nace, y no hay nadie comparable a Él.", "El Profeta ﷺ dijo que este hombre le preguntó a Allah por Su Nombre más grande.", "Cuando se lo pide, Él da; cuando lo llama, Él responde."),
        "dua_thabbitni_hadiyan" to DuaText("Hazme firme, guiado y guía", "Oh Allah, hazme firme y hazme alguien que guíe y sea guiado.", "El Profeta ﷺ hizo este dua para Jarir (RA) (para ti, di 'thabbitni').", "El dua original de Jarir (RA) usa las palabras 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Perdóname y acepta mi arrepentimiento", "Señor mío, perdóname y acepta mi arrepentimiento. De hecho, Tú eres el Aceptador del arrepentimiento, el Misericordioso.", "Cien veces en una sola sesión: la práctica del Profeta ﷺ.", "Los Compañeros contaron que el Profeta ﷺ lo dijo cien veces de una sola vez."),
        "dua_rafiq_ala" to DuaText("Dua del moribundo", "Oh Allah, perdóname, ten piedad de mí y únete a mí con el Compañero Supremo.", "El último dua del Profeta ﷺ: que el enfermo lo diga por sí mismo.", "El Profeta ﷺ hizo esta dua en el momento de su fallecimiento."),
        "dua_la_bas_tahur" to DuaText("Consolar a los enfermos: purificación", "No hay daño; es una purificación (de los pecados), si Allah quiere.", "Para consolar a los enfermos cuando los visitan.", "El Profeta ﷺ dijo esto cuando visitaba a los enfermos."),
        "dua_talqeen" to DuaText("Talqeen para los moribundos", "Nadie tiene derecho a ser adorado excepto Allah.", "Recitar la kalimah cerca de una persona moribunda (no obligarla a decirla).", "Quien diga las últimas palabras 'La ilaha illallah' entrará al Paraíso (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("En lugar de desear la muerte", "Oh Allah, mantenme con vida mientras la vida sea mejor para mí, y llévame cuando la muerte sea mejor para mí.", "En lugar de desear la muerte en las dificultades.", "El Profeta ﷺ prohibió desear la muerte y en su lugar enseñó esto."),
        "dua_for_one_i_cursed" to DuaText("Para alguien a quien lastimé con palabras", "Oh Allah, cualquier creyente a quien haya insultado, haz de ello un medio para acercarse a Ti en el Día de la Resurrección.", "Para alguien con quien hablaste mal con ira.", "Un dua del Profeta ﷺ."),
        "dua_praising_someone" to DuaText("Al elogiar a alguien", "Considero que fulano de tal es así, y Alá es su Calculador, y no garantizo la pureza de nadie ante Alá.", "Al elogiar a alguien, en lugar de exagerar.", "El Profeta ﷺ enseñó esta etiqueta de alabanza."),
        "dua_being_praised" to DuaText("Cuando eres alabado", "Oh Allah, no me hagas responsable de lo que dicen y perdóname por lo que no saben.", "Al oírse elogiar: la práctica de un Compañero (RA).", "Una forma de evitar la arrogancia cuando se elogia."),
        "dua_non_muslim_sneezes" to DuaText("Cuando un no musulmán estornuda", "Que Allah os guíe y arregle vuestros asuntos.", "Cuando un no musulmán estornuda y dice 'Alhamdulillah'.", "Los judíos estornudaban cerca del Profeta ﷺ esperando que dijera 'Yarhamukallah', y él decía esto."),
        "dua_reply_ahl_kitab_salam" to DuaText("Respondiendo al Salam de la Gente del Libro", "Y sobre ti.", "Cuando la Gente del Libro saluda con salam.", "La instrucción del Profeta ﷺ."),
        "dua_fasting_invited" to DuaText("Cuando se le invita durante el ayuno", "Estoy en ayunas.", "Cuando te inviten durante el ayuno, o cuando alguien riña contigo.", "Si la persona que ayuna acepta una invitación, debe orar por el anfitrión."),
        "dua_for_who_gave_drink" to DuaText("Para quien me alimentó", "Oh Allah, alimenta al que me alimentó y dale de beber al que me dio de beber.", "Para quien te dé comida o bebida.", "El Profeta ﷺ hizo este dua para al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Saludo de Eid", "Que Allah acepte (buenas obras) de nosotros y de ustedes.", "Unos a otros en el día de Eid: la práctica de los nobles Compañeros (RA).", "Los Compañeros dijeron esto cuando se reunieron en Eid."),
        "dua_wedding_night" to DuaText("Para la novia después de Nikah", "Oh Allah, te pido por su bien y el bien de la naturaleza con la que la creaste, y busco refugio en Ti de su maldad y del mal de la naturaleza con la que la creaste.", "Después del nikah, colocar la mano sobre la frente de la esposa.", "La enseñanza del Profeta ﷺ: bendición en el matrimonio."),
        "dua_istisqa_ibadak" to DuaText("Riega a tus sirvientes y animales", "Oh Allah, da agua a Tus siervos y a Tus animales, difunde Tu misericordia y da vida a Tu tierra muerta.", "Pidiendo lluvia (istisqa).", "El Profeta ﷺ hizo este dua para la lluvia."),
        "dua_seeing_clouds" to DuaText("Ver nubes oscuras", "Oh Allah, busco refugio en Ti de su maldad.", "Al ver nubes oscuras en el cielo; si llueve, diga 'Allahumma sayyiban nafi'a'.", "Al ver las nubes, el Profeta ﷺ dejaba lo que estaba haciendo y hacía esta dua."),
        "dua_jamarat" to DuaText("Apedreando el Jamarat", "Allah es el Más Grande.", "Con cada piedra lanzada.", "El Profeta ﷺ dijo takbir con cada guijarro, luego, después de la primera y segunda jamrah, se enfrentó a la Qiblah e hizo una larga dua."),
        "dua_rabbi_ainni" to DuaText("Señor mío, ayúdame y no contra mí.", "Señor mío, ayúdame y no ayudes a otros contra mí, concédeme la victoria y no concedas a otros la victoria sobre mí, haz planes para mí y no hagas planes contra mí, guíame y hazme fácil la guía, y ayúdame contra quien me hace daño.", "Un dua completo del Profeta ﷺ (parte inicial).", "Una dua que reúne toda la ayuda en la religión y en este mundo."),
        "dua_ati_nafsi_taqwaha" to DuaText("Concede a mi alma su taqwa", "Oh Allah, concede a mi alma su piedad y purifícala, porque Tú eres el mejor para purificarla. Eres su Guardián y su Maestro.", "Para reformar y purificar el yo.", "El Profeta ﷺ solía hacer este dua."),
        "dua_iqsim_lana_khashyatik" to DuaText("Concédenos tal temor de ti", "Oh Allah, concédenos suficiente temor hacia Ti para interponernos entre nosotros y desobedecerte, suficiente obediencia para llevarnos a Tu Paraíso y suficiente certeza para hacernos fáciles las calamidades de este mundo. Disfrutemos de nuestro oído, de nuestra vista y de nuestras fuerzas mientras Tú nos mantengas vivos y hagas que nos sobrevivan. Véngate de aquellos que nos hacen daño, ayúdanos contra nuestros enemigos, no permitas que nuestra calamidad esté en nuestra religión, no hagas de este mundo nuestra mayor preocupación o el límite de nuestro conocimiento, y no pongas sobre nosotros a aquellos que no tendrán piedad de nosotros.", "Al levantarse de una reunión, el Profeta ﷺ rara vez se levantaba sin hacer esta dua.", "Una dua integral por el bien de la religión, este mundo y el Más Allá."),
        "dua_infani_bima_allamtani" to DuaText("Benefíciame con lo que me enseñaste", "Oh Allah, benefíciame con lo que me has enseñado, enséñame lo que me beneficiará y aumenta mi conocimiento.", "Mientras busca conocimientos o antes de estudiar.", "Un dua para obtener conocimientos beneficiosos y actuar en consecuencia."),
        "dua_jar_su" to DuaText("Refugio de un mal vecino", "Oh Allah, busco refugio en Ti del mal vecino en el lugar de residencia permanente, porque el vecino en un viaje continúa.", "Para protegerse de un mal vecino.", "El Profeta ﷺ ordenó buscar refugio ante esto."),
        "dua_ishfi_abdak" to DuaText("Para la recuperación de una persona enferma", "Oh Allah, cura a Tu siervo para que pueda enfrentarse a un enemigo por Ti o caminar hacia la oración por Ti.", "Por el enfermo al visitarlo.", "El Profeta ﷺ enseñó a decir esto a los enfermos."),
        "dua_la_mania" to DuaText("Nadie puede retener lo que das", "Nadie tiene derecho a ser adorado excepto Allah, solo, sin asociado. Suyo es el dominio y suya la alabanza, y tiene poder sobre todas las cosas. Oh Allah, nadie puede retener lo que Tú das y nadie puede dar lo que Tú retienes, y la riqueza de los ricos no sirve de nada contra Ti.", "Después del salam de la oración obligatoria.", "El Profeta ﷺ dijo esto después de cada oración obligatoria."),
        "dua_slaughtering" to DuaText("Al sacrificar un animal", "En el nombre de Alá, y Alá es el Más Grande.", "Al sacrificar o sacrificar un animal.", "El Profeta ﷺ dijo Bismillah y takbir en el momento del sacrificio."),
    )
}
